-- WASSCE Chemistry 2023 Questions (50 questions)

INSERT OR IGNORE INTO past_papers (id, exam_type_id, subject_id, paper_type_id, year, month, total_questions, total_marks, time_allowed, is_complete)
VALUES ('pp_wassce_chem_2023_1', 'exam_wassce', 'subj_wassce_chemistry', 'paper_wassce_1', 2023, 'May-June', 50, 50, 60, 1);

INSERT OR REPLACE INTO questions (id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, options, correct_answer, explanation, difficulty, marks, question_number) VALUES
-- Atomic Structure (1-10)
('q_chem_2023_001', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'The atomic number of an element is determined by the number of:', 'multiple_choice', '["A. Neutrons", "B. Protons", "C. Electrons", "D. Nucleons"]', 'B', 'The atomic number equals the number of protons in the nucleus, which determines the element identity.', 'easy', 1, 1),
('q_chem_2023_002', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Isotopes of an element have the same number of:', 'multiple_choice', '["A. Neutrons", "B. Mass number", "C. Protons", "D. Nucleons"]', 'C', 'Isotopes have the same number of protons (same atomic number) but different numbers of neutrons.', 'easy', 1, 2),
('q_chem_2023_003', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'The electron configuration of sodium (Na, Z=11) is:', 'multiple_choice', '["A. 2,8,2", "B. 2,8,1", "C. 2,9", "D. 2,8,8"]', 'B', 'Sodium has 11 electrons arranged as 2,8,1 in the first three energy levels.', 'easy', 1, 3),
('q_chem_2023_004', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Which subatomic particle has no charge?', 'multiple_choice', '["A. Proton", "B. Electron", "C. Neutron", "D. Ion"]', 'C', 'Neutrons are electrically neutral particles found in the nucleus along with protons.', 'easy', 1, 4),
('q_chem_2023_005', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'The mass number is the sum of:', 'multiple_choice', '["A. Protons and electrons", "B. Protons and neutrons", "C. Neutrons and electrons", "D. Protons only"]', 'B', 'Mass number = number of protons + number of neutrons (nucleons in the nucleus).', 'easy', 1, 5),
('q_chem_2023_006', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'An atom with 17 protons and 18 neutrons has a mass number of:', 'multiple_choice', '["A. 17", "B. 18", "C. 35", "D. 1"]', 'C', 'Mass number = protons + neutrons = 17 + 18 = 35.', 'easy', 1, 6),
('q_chem_2023_007', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'The maximum number of electrons in the second energy level is:', 'multiple_choice', '["A. 2", "B. 8", "C. 18", "D. 32"]', 'B', 'The maximum electrons in each shell follows 2n², so the second shell (n=2) holds maximum 8 electrons.', 'easy', 1, 7),
('q_chem_2023_008', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Which scientist proposed the nuclear model of the atom?', 'multiple_choice', '["A. Dalton", "B. Thomson", "C. Rutherford", "D. Bohr"]', 'C', 'Ernest Rutherford proposed the nuclear model based on his gold foil experiment, showing a dense positive nucleus.', 'medium', 1, 8),
('q_chem_2023_009', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Cations are formed when atoms:', 'multiple_choice', '["A. Gain electrons", "B. Lose electrons", "C. Share electrons", "D. Gain protons"]', 'B', 'Cations (positive ions) are formed when atoms lose electrons, resulting in more protons than electrons.', 'easy', 1, 9),
('q_chem_2023_010', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'The relative atomic mass of chlorine is 35.5 because:', 'multiple_choice', '["A. It has 35.5 protons", "B. It is a mixture of isotopes", "C. It has 35.5 neutrons", "D. It is radioactive"]', 'B', 'Chlorine exists as two isotopes (Cl-35 and Cl-37) in nature, giving an average relative atomic mass of 35.5.', 'medium', 1, 10),

-- Chemical Bonding (11-20)
('q_chem_2023_011', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'An ionic bond is formed between:', 'multiple_choice', '["A. Two metals", "B. Two non-metals", "C. A metal and a non-metal", "D. Two noble gases"]', 'C', 'Ionic bonds form when a metal transfers electrons to a non-metal, creating oppositely charged ions that attract.', 'easy', 1, 11),
('q_chem_2023_012', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'The bond in hydrogen chloride (HCl) is:', 'multiple_choice', '["A. Ionic", "B. Covalent", "C. Metallic", "D. Hydrogen bond"]', 'B', 'HCl has a covalent bond where hydrogen and chlorine share electrons.', 'easy', 1, 12),
('q_chem_2023_013', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Which compound has a giant covalent structure?', 'multiple_choice', '["A. Sodium chloride", "B. Water", "C. Diamond", "D. Methane"]', 'C', 'Diamond has a giant covalent structure where each carbon atom is covalently bonded to four other carbon atoms.', 'medium', 1, 13),
('q_chem_2023_014', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Metallic bonding involves:', 'multiple_choice', '["A. Transfer of electrons", "B. Sharing of electron pairs", "C. Delocalized electrons", "D. Hydrogen bonds"]', 'C', 'Metallic bonding involves a sea of delocalized electrons shared among positive metal ions.', 'medium', 1, 14),
('q_chem_2023_015', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'The shape of a water molecule is:', 'multiple_choice', '["A. Linear", "B. Trigonal planar", "C. Bent/Angular", "D. Tetrahedral"]', 'C', 'Water has a bent shape due to two lone pairs on oxygen pushing the hydrogen atoms closer together.', 'medium', 1, 15),
('q_chem_2023_016', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Van der Waals forces are:', 'multiple_choice', '["A. Strong intermolecular forces", "B. Weak intermolecular forces", "C. Intramolecular forces", "D. Ionic forces"]', 'B', 'Van der Waals forces are weak intermolecular attractions between molecules, including London dispersion forces.', 'medium', 1, 16),
('q_chem_2023_017', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'A coordinate covalent bond is one where:', 'multiple_choice', '["A. Both atoms donate electrons", "B. One atom donates both electrons", "C. Electrons are transferred", "D. No electrons are shared"]', 'B', 'In a coordinate (dative) covalent bond, one atom provides both electrons to the shared pair.', 'medium', 1, 17),
('q_chem_2023_018', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Graphite conducts electricity because:', 'multiple_choice', '["A. It contains ions", "B. It has metallic bonds", "C. It has delocalized electrons", "D. It contains water"]', 'C', 'Graphite has delocalized electrons between its carbon layers that are free to move and conduct electricity.', 'medium', 1, 18),
('q_chem_2023_019', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Hydrogen bonding is strongest in:', 'multiple_choice', '["A. HCl", "B. H2O", "C. H2S", "D. CH4"]', 'B', 'Water has strong hydrogen bonding because oxygen is highly electronegative and small, creating strong H-bonds.', 'medium', 1, 19),
('q_chem_2023_020', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'The bond angle in methane (CH4) is approximately:', 'multiple_choice', '["A. 90°", "B. 104.5°", "C. 109.5°", "D. 120°"]', 'C', 'Methane has a tetrahedral shape with bond angles of approximately 109.5°.', 'medium', 1, 20),

-- Acids, Bases, and Salts (21-30)
('q_chem_2023_021', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'The pH of a neutral solution is:', 'multiple_choice', '["A. 0", "B. 7", "C. 14", "D. 1"]', 'B', 'A neutral solution has a pH of 7, where the concentration of H+ equals OH- ions.', 'easy', 1, 21),
('q_chem_2023_022', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Which indicator turns pink in alkaline solution?', 'multiple_choice', '["A. Methyl orange", "B. Litmus", "C. Phenolphthalein", "D. Bromothymol blue"]', 'C', 'Phenolphthalein is colorless in acid and turns pink in alkaline solutions.', 'easy', 1, 22),
('q_chem_2023_023', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'When an acid reacts with a base, the products are:', 'multiple_choice', '["A. Salt only", "B. Water only", "C. Salt and water", "D. Salt and hydrogen"]', 'C', 'Neutralization: Acid + Base → Salt + Water. This is a neutralization reaction.', 'easy', 1, 23),
('q_chem_2023_024', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'A strong acid is one that:', 'multiple_choice', '["A. Has a high pH", "B. Is completely ionized in solution", "C. Is partially ionized", "D. Does not conduct electricity"]', 'B', 'Strong acids completely dissociate in water, releasing all their hydrogen ions.', 'medium', 1, 24),
('q_chem_2023_025', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'The salt formed when HCl reacts with NaOH is:', 'multiple_choice', '["A. Sodium sulfate", "B. Sodium chloride", "C. Sodium nitrate", "D. Sodium carbonate"]', 'B', 'HCl + NaOH → NaCl + H2O. Sodium chloride (table salt) is formed.', 'easy', 1, 25),
('q_chem_2023_026', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Effervescence occurs when acids react with:', 'multiple_choice', '["A. Oxides", "B. Hydroxides", "C. Carbonates", "D. Sulfates"]', 'C', 'Carbonates react with acids to produce carbon dioxide gas, causing effervescence (bubbling).', 'easy', 1, 26),
('q_chem_2023_027', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'A buffer solution:', 'multiple_choice', '["A. Changes pH rapidly", "B. Resists changes in pH", "C. Has pH of 14", "D. Contains only acids"]', 'B', 'A buffer solution resists changes in pH when small amounts of acid or base are added.', 'hard', 1, 27),
('q_chem_2023_028', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Hydrochloric acid is a:', 'multiple_choice', '["A. Weak acid", "B. Strong acid", "C. Weak base", "D. Strong base"]', 'B', 'Hydrochloric acid (HCl) is a strong acid that completely dissociates in water.', 'easy', 1, 28),
('q_chem_2023_029', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'The basicity of H2SO4 is:', 'multiple_choice', '["A. 1", "B. 2", "C. 3", "D. 4"]', 'B', 'Sulfuric acid (H2SO4) has basicity of 2 as it can donate two hydrogen ions per molecule.', 'medium', 1, 29),
('q_chem_2023_030', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Deliquescent substances:', 'multiple_choice', '["A. Lose water to atmosphere", "B. Absorb water and dissolve", "C. Do not absorb water", "D. Decompose in water"]', 'B', 'Deliquescent substances absorb moisture from the air and dissolve in it to form a solution.', 'medium', 1, 30),

-- Redox Reactions and Electrochemistry (31-40)
('q_chem_2023_031', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Oxidation involves:', 'multiple_choice', '["A. Gain of electrons", "B. Loss of electrons", "C. Gain of protons", "D. Loss of neutrons"]', 'B', 'Oxidation is the loss of electrons (or increase in oxidation state). Remember OIL RIG.', 'easy', 1, 31),
('q_chem_2023_032', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'In electrolysis, reduction occurs at the:', 'multiple_choice', '["A. Anode", "B. Cathode", "C. Electrolyte", "D. Salt bridge"]', 'B', 'Reduction (gain of electrons) occurs at the cathode (negative electrode) during electrolysis.', 'easy', 1, 32),
('q_chem_2023_033', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'The oxidation state of oxygen in most compounds is:', 'multiple_choice', '["A. +2", "B. -2", "C. 0", "D. +1"]', 'B', 'Oxygen typically has an oxidation state of -2 in compounds (except in peroxides and OF2).', 'easy', 1, 33),
('q_chem_2023_034', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'During electrolysis of brine, chlorine is produced at the:', 'multiple_choice', '["A. Cathode", "B. Anode", "C. Salt bridge", "D. Neither electrode"]', 'B', 'Chloride ions are oxidized at the anode to form chlorine gas: 2Cl⁻ → Cl2 + 2e⁻', 'medium', 1, 34),
('q_chem_2023_035', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'A reducing agent is a substance that:', 'multiple_choice', '["A. Gains electrons", "B. Loses electrons", "C. Gains protons", "D. Loses protons"]', 'B', 'A reducing agent donates electrons to another substance, becoming oxidized in the process.', 'medium', 1, 35),
('q_chem_2023_036', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Electroplating uses the principle of:', 'multiple_choice', '["A. Electrolysis", "B. Distillation", "C. Crystallization", "D. Combustion"]', 'A', 'Electroplating uses electrolysis to deposit a thin layer of metal onto an object.', 'easy', 1, 36),
('q_chem_2023_037', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'In a galvanic cell, electrical energy is produced from:', 'multiple_choice', '["A. Heat energy", "B. Chemical energy", "C. Light energy", "D. Nuclear energy"]', 'B', 'Galvanic (voltaic) cells convert chemical energy to electrical energy through spontaneous redox reactions.', 'medium', 1, 37),
('q_chem_2023_038', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'The oxidation state of manganese in KMnO4 is:', 'multiple_choice', '["A. +2", "B. +4", "C. +6", "D. +7"]', 'D', 'In KMnO4: K(+1) + Mn(x) + 4O(-2) = 0, so x = +7.', 'hard', 1, 38),
('q_chem_2023_039', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Faraday''s law relates the mass of substance deposited to:', 'multiple_choice', '["A. Temperature", "B. Quantity of electricity", "C. Pressure", "D. Volume"]', 'B', 'Faraday''s law states that the mass deposited is proportional to the quantity of electricity passed.', 'medium', 1, 39),
('q_chem_2023_040', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Rusting of iron is an example of:', 'multiple_choice', '["A. Reduction", "B. Oxidation", "C. Neutralization", "D. Hydrolysis"]', 'B', 'Rusting is an oxidation process where iron loses electrons to form iron oxide (rust).', 'easy', 1, 40),

-- Organic Chemistry and Rates (41-50)
('q_chem_2023_041', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'The general formula for alkanes is:', 'multiple_choice', '["A. CnH2n", "B. CnH2n+2", "C. CnH2n-2", "D. CnHn"]', 'B', 'Alkanes have the general formula CnH2n+2, where n is the number of carbon atoms.', 'easy', 1, 41),
('q_chem_2023_042', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Ethene belongs to the homologous series of:', 'multiple_choice', '["A. Alkanes", "B. Alkenes", "C. Alkynes", "D. Alcohols"]', 'B', 'Ethene (C2H4) is an alkene, characterized by a carbon-carbon double bond.', 'easy', 1, 42),
('q_chem_2023_043', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'The functional group in alcohols is:', 'multiple_choice', '["A. -COOH", "B. -OH", "C. -CHO", "D. -CO-"]', 'B', 'Alcohols contain the hydroxyl (-OH) functional group attached to a carbon atom.', 'easy', 1, 43),
('q_chem_2023_044', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Fermentation of glucose produces:', 'multiple_choice', '["A. Methanol", "B. Ethanol", "C. Propanol", "D. Butanol"]', 'B', 'Fermentation of glucose by yeast produces ethanol and carbon dioxide.', 'easy', 1, 44),
('q_chem_2023_045', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Isomers are compounds with the same:', 'multiple_choice', '["A. Structural formula", "B. Molecular formula but different structures", "C. Physical properties", "D. Chemical properties"]', 'B', 'Isomers have the same molecular formula but different structural arrangements.', 'medium', 1, 45),
('q_chem_2023_046', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'A catalyst increases reaction rate by:', 'multiple_choice', '["A. Increasing temperature", "B. Lowering activation energy", "C. Increasing concentration", "D. Increasing pressure"]', 'B', 'Catalysts lower the activation energy, providing an alternative reaction pathway.', 'medium', 1, 46),
('q_chem_2023_047', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'The IUPAC name for CH3COOH is:', 'multiple_choice', '["A. Methanoic acid", "B. Ethanoic acid", "C. Propanoic acid", "D. Butanoic acid"]', 'B', 'CH3COOH has two carbon atoms and a carboxylic acid group, so it is ethanoic acid (acetic acid).', 'easy', 1, 47),
('q_chem_2023_048', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Polymerization is the process of:', 'multiple_choice', '["A. Breaking down polymers", "B. Joining monomers to form polymers", "C. Separating mixtures", "D. Purifying compounds"]', 'B', 'Polymerization joins many small monomer units together to form large polymer molecules.', 'easy', 1, 48),
('q_chem_2023_049', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Increasing temperature increases reaction rate because:', 'multiple_choice', '["A. It decreases collisions", "B. Particles have more energy and collide more frequently", "C. It acts as a catalyst", "D. It decreases activation energy"]', 'B', 'Higher temperature means particles have more kinetic energy, leading to more frequent and energetic collisions.', 'medium', 1, 49),
('q_chem_2023_050', 'subj_wassce_chemistry', 'exam_wassce', 'paper_wassce_1', 'pp_wassce_chem_2023_1', 'Saponification is used to make:', 'multiple_choice', '["A. Plastics", "B. Soap", "C. Ethanol", "D. Vinegar"]', 'B', 'Saponification is the reaction of fats/oils with alkali to produce soap and glycerol.', 'easy', 1, 50);
